#### ב. החלפת פונקציות העיטורים `getHeadingOrnamentHTML` ו-`renderSideOrnamentHTML`:
**החלף את שורות 65–110 בערך (מתחיל ב-`function getHeadingOrnamentHTML` ומסתיים בסוף `renderSideOrnamentHTML`):**
```javascript
// עיטור עליון או תחתון לכותרת 2 (נלקח אך ורק מתוך ornaments_up_down.json)
function getHeadingOrnamentHTML(type, isTop = false) {
  if (!type || type === 'none') return '';
  const flipStyle = isTop ? 'transform: scaleY(-1);' : '';
  let inner = '';

  if (ORNAMENTS_UD[type]) {
    inner = `<div style="display:inline-flex; align-items:center; justify-content:center; ${flipStyle}">${ORNAMENTS_UD[type].svg}</div>`;
  } else if (type === 'custom_img') {
    const imgSrc = document.getElementById('data-sec-div-img')?.value || '';
    if (imgSrc) inner = `<img src="${imgSrc}" style="max-width: 200px; max-height: 35px; margin: auto; display: block; object-fit: contain; ${flipStyle}" />`;
  }
  return inner ? `<div class="heading-ornament-wrap" style="text-align:center; margin: 6px auto;">${inner}</div>` : '';
}

// עיטורי צד לכותרת 3 (נלקחים אך ורק מתוך ornaments_left_right.json)
function renderSideOrnamentHTML(styleKey, isLeft = false) {
  if (!styleKey || styleKey === 'none') return '';
  const flipStyle = isLeft ? 'transform: scaleX(-1);' : '';

  if (ORNAMENTS_LR[styleKey]) {
    return `<span class="side-ornament-wrap" style="display:inline-flex; align-items:center; ${flipStyle}">${ORNAMENTS_LR[styleKey].svg}</span>`;
  } else if (styleKey === 'custom_img') {
    const imgSrc = document.getElementById('data-hdr-c-img')?.value || document.getElementById('data-sec-div-img')?.value || '';
    return imgSrc ? `<img src="${imgSrc}" style="max-height: 18px; max-width: 60px; object-fit: contain; vertical-align: middle; ${flipStyle}" />` : '';
  }
  return '';
}
```

